func newPositioning() unsafe.Pointer { return unsafe.Pointer(new(driverpositioning.Positioning)) }

func newNPositioning(n int) unsafe.Pointer {
	return unsafe.Pointer(unsafe.SliceData(make([]driverpositioning.Positioning, n)))
}

func ptrPositioning(p unsafe.Pointer, c int32) any {
	r := (*driverpositioning.Positioning)(p)
	switch c {
	case 0:
		return (*string)(unsafe.Pointer(&r.ID))
	case 1:
		return (*string)(unsafe.Pointer(&r.BusinessUnitID))
	case 2:
		return (*string)(unsafe.Pointer(&r.OrganizationID))
	case 3:
		return (*string)(unsafe.Pointer(&r.WorkerID))
	case 4:
		return &r.FromCell
	case 5:
		return &r.FromLabel
	case 6:
		return &r.ToCell
	case 7:
		return &r.ToLabel
	case 8:
		return &r.ToLatitude
	case 9:
		return &r.ToLongitude
	case 10:
		return &r.SlotStart
	case 11:
		return &r.FreeAt
	case 12:
		return &r.ArriveAt
	case 13:
		return &r.Miles
	case 14:
		return &r.ValueCents
	case 15:
		return (*string)(unsafe.Pointer(&r.Status))
	case 16:
		return (*string)(unsafe.Pointer(&r.CreatedByID))
	case 17:
		return (*string)(unsafe.Pointer(&r.CanceledByID))
	case 18:
		return &r.CanceledAt
	case 19:
		return &r.Version
	case 20:
		return &r.CreatedAt
	case 21:
		return &r.UpdatedAt
	}
	return nil
}

func valuePositioning(p unsafe.Pointer, c int32) any {
	r := (*driverpositioning.Positioning)(p)
	switch c {
	case 0:
		return string(r.ID)
	case 1:
		return string(r.BusinessUnitID)
	case 2:
		return string(r.OrganizationID)
	case 3:
		return string(r.WorkerID)
	case 4:
		return r.FromCell
	case 5:
		return r.FromLabel
	case 6:
		return r.ToCell
	case 7:
		return r.ToLabel
	case 8:
		return r.ToLatitude
	case 9:
		return r.ToLongitude
	case 10:
		return r.SlotStart
	case 11:
		return r.FreeAt
	case 12:
		return r.ArriveAt
	case 13:
		return r.Miles
	case 14:
		return r.ValueCents
	case 15:
		return string(r.Status)
	case 16:
		if r.CreatedByID == "" {
			return nil
		}
		return string(r.CreatedByID)
	case 17:
		if r.CanceledByID == "" {
			return nil
		}
		return string(r.CanceledByID)
	case 18:
		if r.CanceledAt == nil {
			return nil
		}
		return *r.CanceledAt
	case 19:
		return r.Version
	case 20:
		return r.CreatedAt
	case 21:
		return r.UpdatedAt
	}
	return nil
}

